import sys, itertools
sys.path.insert(0, 'src')
from accountability.authorization import intersection_pattern, pattern_matches

alpha = "ab"
def pats():
    out = set()
    for n in range(1,6):
        for chars in itertools.product(alpha+"*", repeat=n):
            if "".join(chars).count("*")>=1:
                out.add("".join(chars))
    return sorted(out)

def middles(p):
    parts = p.split("*")
    return tuple(x for x in parts[1:-1] if x)

def is_subseq(needle, hay):
    i=0
    for x in hay:
        if i < len(needle) and needle[i]==x: i+=1
    return i==len(needle)

strings = ["".join(c) for n in range(0,6) for c in itertools.product(alpha, repeat=n)]
checked=0
for a in pats():
    for b in pats():
        p = intersection_pattern(a,b)
        p2 = intersection_pattern(b,a)
        assert p == p2, ("symmetry", a, b, p, p2)
        if p is None: continue
        ma, mb, mp = middles(a), middles(b), middles(p)
        assert is_subseq(ma, mp) and is_subseq(mb, mp), ("embed", a,b,p)
        for s in strings:
            if pattern_matches(p,s):
                assert pattern_matches(a,s) and pattern_matches(b,s), ("lang",a,b,p,s)
        for t in set(ma)|set(mb):
            assert mp.count(t) == max(ma.count(t), mb.count(t)), ("mult",a,b,p)
        checked+=1
print("exhaustive pair checks:", checked, "all good")
